/* Polvo brillante: movimiento permanente mientras esté activado, también sobre las tarjetas. */
const Ambient=(()=>{
 const canvas=document.getElementById('canvas-ambient'),ctx=canvas.getContext('2d');let enabled=true,particles=[],w=0,h=0,last=0;
 function resize(){const dpr=Math.min(window.devicePixelRatio||1,window.innerWidth<600?1.25:2);w=window.innerWidth;h=window.innerHeight;canvas.width=Math.round(w*dpr);canvas.height=Math.round(h*dpr);ctx.setTransform(dpr,0,0,dpr,0,0);particles=Array.from({length:window.innerWidth<600?42:window.innerWidth<1000?60:85},()=>({x:Math.random()*w,y:Math.random()*h,r:Math.random()*1.5+.65,speed:Math.random()*.65+.25,alpha:Math.random()*.45+.35,phase:Math.random()*Math.PI*2}))}
 function frame(now){const dt=Math.min((now-last)/16.67||1,3);last=now;ctx.clearRect(0,0,w,h);if(enabled){ctx.globalCompositeOperation='screen';for(const p of particles){const a=p.alpha*(.7+.3*Math.sin(now*.002+p.phase));const glow=ctx.createRadialGradient(p.x,p.y,0,p.x,p.y,p.r*5);glow.addColorStop(0,`rgba(255,244,185,${a})`);glow.addColorStop(.3,`rgba(255,200,95,${a*.4})`);glow.addColorStop(1,'rgba(255,180,40,0)');ctx.fillStyle=glow;ctx.beginPath();ctx.arc(p.x,p.y,p.r*5,0,Math.PI*2);ctx.fill();p.y-=p.speed*dt;p.x+=Math.sin(p.y*.012+p.phase)*.3*dt;if(p.y< -25){p.y=h+25;p.x=Math.random()*w}}ctx.globalCompositeOperation='source-over'}requestAnimationFrame(frame)}
 window.addEventListener('resize',resize);window.addEventListener('orientationchange',()=>setTimeout(resize,150));resize();requestAnimationFrame(frame);return {setEnabled:v=>enabled=!!v};
})();
